@@ -53,5 +53,40 @@ app.kubernetes.io/part-of: shoal-platform
 {{- .Values.compactor.enabled -}}
 {{- else -}}
 {{- eq .Values.mode "accumulo" -}}
 {{- end -}}
 {{- end -}}
+
+{{- define "shoal.explorerEnabled" -}}
+{{- .Values.explorer.enabled -}}
+{{- end -}}
+
+{{- /*
+Explorer names are built from one bounded stem so that every name derived from
+it fits Kubernetes' 63-character limit.
+
+Truncating the finished name is not enough: the headless Service name is the
+longest of them, and appending "-headless" to an already-63-character name
+produces 72. The stem reserves room for the longest suffix instead, so a long
+release name shortens the stem rather than overflowing the name.
+
+  stem            45
+  -explorer        9  -> 54
+  -explorer-headless 18 -> 63
+*/ -}}
+{{- define "shoal.explorerStem" -}}
+{{- include "shoal.fullname" . | trunc 45 | trimSuffix "-" -}}
+{{- end -}}
+
+{{- define "shoal.explorerName" -}}
+{{- printf "%s-explorer" (include "shoal.explorerStem" .) -}}
+{{- end -}}
+
+{{- define "shoal.explorerHeadlessName" -}}
+{{- printf "%s-explorer-headless" (include "shoal.explorerStem" .) -}}
+{{- end -}}
+
+{{- define "shoal.explorerSelectorLabels" -}}
+app.kubernetes.io/name: shoal-explore-web
+app.kubernetes.io/instance: {{ .Release.Name }}
+app.kubernetes.io/component: explorer
+{{- end -}}
diff --git a/deploy/helm/shoal/templates/explorer-poddisruptionbudget.yaml b/deploy/helm/shoal/templates/explorer-poddisruptionbudget.yaml
new file mode 100644
index 0000000..7d0fef8
--- /dev/null
+++ b/deploy/helm/shoal/templates/explorer-poddisruptionbudget.yaml
@@ -0,0 +1,19 @@
+{{- if and (eq (include "shoal.explorerEnabled" .) "true") .Values.explorer.podDisruptionBudget.enabled }}
+apiVersion: policy/v1
+kind: PodDisruptionBudget
+metadata:
+  name: {{ include "shoal.explorerName" . }}
+  labels:
+    {{- include "shoal.labels" . | nindent 4 }}
+    app.kubernetes.io/component: explorer
+spec:
+  # maxUnavailable: 0 means the Eviction API (kubectl drain,
+  # cluster-autoscaler consolidation) refuses to evict this pod rather than
+  # taking the only authorized plane offline. It does NOT block an
+  # operator-initiated rolling update: the StatefulSet controller replaces pods
+  # directly and is not subject to PDBs.
+  maxUnavailable: {{ .Values.explorer.podDisruptionBudget.maxUnavailable }}
+  selector:
+    matchLabels:
+      {{- include "shoal.explorerSelectorLabels" . | nindent 6 }}
+{{- end }}
diff --git a/deploy/helm/shoal/templates/explorer-service.yaml b/deploy/helm/shoal/templates/explorer-service.yaml
new file mode 100644
index 0000000..843ca71
--- /dev/null
+++ b/deploy/helm/shoal/templates/explorer-service.yaml
@@ -0,0 +1,41 @@
+{{- if eq (include "shoal.explorerEnabled" .) "true" }}
+apiVersion: v1
+kind: Service
+metadata:
+  name: {{ include "shoal.explorerName" . }}
+  labels:
+    {{- include "shoal.labels" . | nindent 4 }}
+    app.kubernetes.io/component: explorer
+  {{- with .Values.explorer.service.annotations }}
+  annotations:
+    {{- toYaml . | nindent 4 }}
+  {{- end }}
+spec:
+  type: {{ .Values.explorer.service.type }}
+  selector:
+    {{- include "shoal.explorerSelectorLabels" . | nindent 4 }}
+  ports:
+    - name: http
+      port: {{ .Values.explorer.servicePort }}
+      targetPort: http
+---
+# Headless governing Service for the StatefulSet. It carries no health port:
+# the probe surface is for the kubelet, which reaches the pod directly, and
+# publishing it would make an unauthenticated endpoint routable in-cluster for
+# no reason.
+apiVersion: v1
+kind: Service
+metadata:
+  name: {{ include "shoal.explorerHeadlessName" . }}
+  labels:
+    {{- include "shoal.labels" . | nindent 4 }}
+    app.kubernetes.io/component: explorer
+spec:
+  clusterIP: None
+  selector:
+    {{- include "shoal.explorerSelectorLabels" . | nindent 4 }}
+  ports:
+    - name: http
+      port: {{ .Values.explorer.servicePort }}
+      targetPort: http
+{{- end }}
diff --git a/deploy/helm/shoal/templates/explorer-statefulset.yaml b/deploy/helm/shoal/templates/explorer-statefulset.yaml
new file mode 100644
index 0000000..d9fcb2a
--- /dev/null
+++ b/deploy/helm/shoal/templates/explorer-statefulset.yaml
@@ -0,0 +1,230 @@
+{{- if eq (include "shoal.explorerEnabled" .) "true" }}
+{{- $explorer := .Values.explorer -}}
+{{- $oidc := $explorer.auth.oidc -}}
+apiVersion: apps/v1
+kind: StatefulSet
+metadata:
+  name: {{ include "shoal.explorerName" . }}
+  labels:
+    {{- include "shoal.labels" . | nindent 4 }}
+    app.kubernetes.io/component: explorer
+spec:
+  # A StatefulSet rather than a Deployment, and not for ordinal identity: its
+  # rolling update stops the old pod before starting the new one. A Deployment
+  # surges by default, which would put two processes on one ReadWriteOnce state
+  # root — the split-brain the workspace has no protocol for.
+  replicas: {{ $explorer.replicas }}
+  serviceName: {{ include "shoal.explorerHeadlessName" . }}
+  podManagementPolicy: OrderedReady
+  updateStrategy:
+    type: RollingUpdate
+    rollingUpdate:
+      partition: {{ $explorer.updateStrategy.partition }}
+  selector:
+    matchLabels:
+      {{- include "shoal.explorerSelectorLabels" . | nindent 6 }}
+  template:
+    metadata:
+      labels:
+        {{- include "shoal.explorerSelectorLabels" . | nindent 8 }}
+        app.kubernetes.io/part-of: shoal-platform
+    spec:
+      # Every setting is an argument on this pod spec rather than a ConfigMap.
+      # A changed argument changes the pod template and rolls the pod on its
+      # own; a ConfigMap would need a checksum annotation to get the same
+      # effect, and without one an edited disclosure setting would leave the
+      # running process on the old posture while the chart claimed the new one.
+      terminationGracePeriodSeconds: {{ $explorer.terminationGracePeriodSeconds }}
+      securityContext:
+        runAsNonRoot: true
+        runAsUser: 65532
+        runAsGroup: 65532
+        fsGroup: 65532
+        seccompProfile:
+          type: RuntimeDefault
+      {{- with $explorer.nodeSelector }}
+      nodeSelector:
+        {{- toYaml . | nindent 8 }}
+      {{- end }}
+      {{- with $explorer.tolerations }}
+      tolerations:
+        {{- toYaml . | nindent 8 }}
+      {{- end }}
+      {{- with $explorer.affinity }}
+      affinity:
+        {{- toYaml . | nindent 8 }}
+      {{- end }}
+      containers:
+        - name: shoal-explore-web
+          image: "{{ $explorer.image.repository }}:{{ $explorer.image.tag }}"
+          imagePullPolicy: {{ $explorer.image.pullPolicy }}
+          command: ["/usr/local/bin/shoal-explore-web"]
+          args:
+            # One state root: -state-dir places the corpus and the durable
+            # policy catalog beneath it, so the single mount below persists
+            # everything a restart needs.
+            - -state-dir={{ $explorer.stateDir }}
+            - -listen=0.0.0.0:{{ $explorer.containerPort }}
+            - -health-address=0.0.0.0:{{ $explorer.healthPort }}
+            - -allowed-host={{ join "," $explorer.allowedHosts }}
+            {{- if $explorer.disclosure.concealWithholding }}
+            - -conceal-withholding
+            {{- end }}
+            {{- if gt (int $explorer.disclosure.mosaic.maxDomains) 0 }}
+            - -mosaic-budget={{ $explorer.disclosure.mosaic.maxDomains }}
+            - -mosaic-window={{ $explorer.disclosure.mosaic.window }}
+            {{- end }}
+            - -oidc-issuer={{ $oidc.issuer }}
+            - -oidc-audience={{ join "," $oidc.audiences }}
+            - -oidc-authorization-claim={{ $oidc.authorizationClaim }}
+            {{- with $oidc.discoveryURL }}
+            - -oidc-discovery-url={{ . }}
+            {{- end }}
+            {{- with $oidc.jwksURI }}
+            - -oidc-jwks-uri={{ . }}
+            {{- end }}
+            {{- with $oidc.allowedAlgs }}
+            - -oidc-allowed-algs={{ . }}
+            {{- end }}
+            {{- with $oidc.clockSkew }}
+            - -oidc-clock-skew={{ . }}
+            {{- end }}
+            {{- with $oidc.subjectClaim }}
+            - -oidc-subject-claim={{ . }}
+            {{- end }}
+            {{- with $oidc.actorClaim }}
+            - -oidc-actor-claim={{ . }}
+            {{- end }}
+            {{- with $oidc.clientIDClaim }}
+            - -oidc-client-id-claim={{ . }}
+            {{- end }}
+            {{- with $oidc.delegationClaim }}
+            - -oidc-delegation-claim={{ . }}
+            {{- end }}
+            {{- with $oidc.readerValues }}
+            - -oidc-reader-values={{ join "," . }}
+            {{- end }}
+            {{- with $oidc.contributorValues }}
+            - -oidc-contributor-values={{ join "," . }}
+            {{- end }}
+            {{- with $oidc.fleetValues }}
+            - -oidc-fleet-values={{ join "," . }}
+            {{- end }}
+            {{- with $oidc.browserClientID }}
+            - -oidc-browser-client-id={{ . }}
+            {{- end }}
+            {{- with $oidc.browserScope }}
+            - -oidc-browser-scope={{ . }}
+            {{- end }}
+            {{- with $explorer.chat.provider }}
+            - -chat-provider={{ . }}
+            - -chat-model={{ $explorer.chat.model }}
+            - -chat-base-url={{ $explorer.chat.baseURL }}
+            - -chat-api-key-env={{ $explorer.chat.apiKeyEnv }}
+            {{- with $explorer.chat.organization }}
+            - -chat-organization={{ . }}
+            {{- end }}
+            {{- with $explorer.chat.project }}
+            - -chat-project={{ . }}
+            {{- end }}
+            {{- end }}
+            {{- with $explorer.embedding.provider }}
+            - -embedding-provider={{ . }}
+            - -embedding-model={{ $explorer.embedding.model }}
+            - -embedding-dimensions={{ $explorer.embedding.dimensions }}
+            {{- with $explorer.embedding.baseURL }}
+            - -embedding-base-url={{ . }}
+            {{- end }}
+            - -embedding-api-key-env={{ $explorer.embedding.apiKeyEnv }}
+            {{- end }}
+            {{- with $explorer.fleet.executorRefs }}
+            - -fleet-executor-refs={{ join "," . }}
+            {{- end }}
+            {{- with $explorer.fleet.askExecutorRef }}
+            - -fleet-ask-executor-ref={{ . }}
+            {{- end }}
+            {{- with $explorer.ontologyFile }}
+            - -ontology-file={{ . }}
+            {{- end }}
+          {{- if or (and $explorer.chat.credentialSecretName $explorer.chat.provider) (and $explorer.embedding.credentialSecretName $explorer.embedding.provider) }}
+          env:
+            {{- if and $explorer.chat.credentialSecretName $explorer.chat.provider }}
+            - name: {{ $explorer.chat.apiKeyEnv }}
+              valueFrom:
+                secretKeyRef:
+                  name: {{ $explorer.chat.credentialSecretName }}
+                  key: {{ $explorer.chat.credentialSecretKey }}
+            {{- end }}
+            {{- if and $explorer.embedding.credentialSecretName $explorer.embedding.provider }}
+            - name: {{ $explorer.embedding.apiKeyEnv }}
+              valueFrom:
+                secretKeyRef:
+                  name: {{ $explorer.embedding.credentialSecretName }}
+                  key: {{ $explorer.embedding.credentialSecretKey }}
+            {{- end }}
+          {{- end }}
+          ports:
+            - name: http
+              containerPort: {{ $explorer.containerPort }}
+            - name: health
+              containerPort: {{ $explorer.healthPort }}
+          volumeMounts:
+            - name: state
+              mountPath: {{ $explorer.stateDir }}
+            # The root filesystem is read-only, and the engine writes temporary
+            # files outside the state root on some paths (for example
+            # internal/engine/rfile_export.go, which creates its verification
+            # file in the system temp directory). An emptyDir keeps those
+            # working without giving the rest of the root back.
+            - name: tmp
+              mountPath: /tmp
+          # Both probes address the health port, never the workspace port. The
+          # workspace refuses any request whose Host is not an exactly
+          # configured authority, and a kubelet addresses the pod by its
+          # runtime-assigned IP, which allowedHosts cannot name. A probe there
+          # answers 421 and the pod never becomes ready.
+          readinessProbe:
+            httpGet:
+              path: /readyz
+              port: health
+            initialDelaySeconds: 3
+            periodSeconds: 5
+            failureThreshold: 3
+          livenessProbe:
+            httpGet:
+              path: /healthz
+              port: health
+            initialDelaySeconds: 15
+            periodSeconds: 20
+          # The corpus and policy catalog can take a while to open on a large
+          # state root. A startup probe gives that time without also making the
+          # liveness probe slow to notice a wedged process afterwards.
+          startupProbe:
+            httpGet:
+              path: /healthz
+              port: health
+            periodSeconds: 5
+            failureThreshold: 60
+          resources:
+            {{- toYaml $explorer.resources | nindent 12 }}
+          securityContext:
+            allowPrivilegeEscalation: false
+            readOnlyRootFilesystem: true
+            capabilities:
+              drop: ["ALL"]
+      volumes:
+        - name: tmp
+          emptyDir: {}
+  volumeClaimTemplates:
+    - metadata:
+        name: state
+      spec:
+        # ReadWriteOnce is the honest access mode: one process owns this engine.
+        accessModes: ["ReadWriteOnce"]
+        {{- with $explorer.storageClassName }}
+        storageClassName: {{ . }}
+        {{- end }}
+        resources:
+          requests:
+            storage: {{ $explorer.storageSize }}
+{{- end }}
diff --git a/deploy/helm/shoal/templates/validate.yaml b/deploy/helm/shoal/templates/validate.yaml
index 5c3e0b7..91eb29a 100644
--- a/deploy/helm/shoal/templates/validate.yaml
+++ b/deploy/helm/shoal/templates/validate.yaml
@@ -8,5 +8,116 @@
 {{- fail "invalid write authority configuration: Shoal-only writeTier and Accumulo tserver cannot both be enabled" -}}
 {{- end -}}
 {{- if and (eq .Values.mode "distributed") $writeTierEnabled (gt (int .Values.writeTier.replicas) 1) -}}
 {{- fail "distributed mode supports exactly one writable writeTier replica until the Kubernetes Lease adapter exists" -}}
 {{- end -}}
+{{- if eq (include "shoal.explorerEnabled" .) "true" -}}
+{{- $explorer := .Values.explorer -}}
+{{- $oidc := $explorer.auth.oidc -}}
+
+{{- /* Authentication is a required decision, and OIDC is the only valid one.
+       -dev-auth is refused on any non-loopback listener, and a pod reached
+       through a Service must bind one, so a chart could only render it into a
+       workspace that cannot start. */ -}}
+{{- if ne $explorer.auth.mode "oidc" -}}
+{{- fail (printf "explorer.auth.mode must be set to \"oidc\" (got %q). The Explorer refuses to serve without an authenticator, and -dev-auth is not an option in a cluster: it is refused on any non-loopback listener, which a pod behind a Service must bind. Configure explorer.auth.oidc" $explorer.auth.mode) -}}
+{{- end -}}
+{{- /* Every required value is checked after trimming, and list values are
+       checked item by item.
+
+       A value that is present but blank is not a configured value. The
+       workspace drops empty entries in normalizeRequiredValues and then
+       reports the setting as missing, so a list holding only "" or " " renders
+       a pod that starts and exits during OIDC initialisation — the failure
+       these guards exist to move to render time. Length alone would pass it. */ -}}
+{{- if not (trim $oidc.issuer) -}}
+{{- fail "explorer.auth.oidc.issuer is required: tokens are validated against an exact issuer" -}}
+{{- end -}}
+{{- $audiences := list -}}
+{{- range $oidc.audiences }}{{- if trim . }}{{- $audiences = append $audiences (trim .) }}{{- end }}{{- end -}}
+{{- if not $audiences -}}
+{{- fail "explorer.auth.oidc.audiences needs at least one non-blank value: at least one audience must match a token exactly, or every token is rejected" -}}
+{{- end -}}
+{{- if not (trim $oidc.authorizationClaim) -}}
+{{- fail "explorer.auth.oidc.authorizationClaim is required: without it no token carries workspace authority and every authenticated caller is denied" -}}
+{{- end -}}
+{{- /* A mapped claim with no values is fail-closed but indistinguishable from
+       an outage, and it is the most common way to deploy a workspace that
+       authenticates everyone and authorizes no one. */ -}}
+{{- $roleValues := list -}}
+{{- range (concat $oidc.readerValues $oidc.contributorValues $oidc.fleetValues) }}{{- if trim . }}{{- $roleValues = append $roleValues (trim .) }}{{- end }}{{- end -}}
+{{- if not $roleValues -}}
+{{- fail "explorer.auth.oidc needs at least one non-blank value across readerValues, contributorValues and fleetValues: the authorization claim is mapped to nothing, so every authenticated caller would be denied" -}}
+{{- end -}}
+
+{{- /* An empty allow-list refuses every request with 421, because the resolved
+       listen address of a pod is an authority no real client sends. */ -}}
+{{- $allowedHosts := list -}}
+{{- range $explorer.allowedHosts }}{{- if trim . }}{{- $allowedHosts = append $allowedHosts (trim .) }}{{- end }}{{- end -}}
+{{- if not $allowedHosts -}}
+{{- fail "explorer.allowedHosts needs at least one non-blank value: the workspace binds a non-loopback address in a pod, and with no allow-list every request is refused with 421 Misdirected Request. List the external authority clients actually send (usually the port-less ingress name)" -}}
+{{- end -}}
+
+{{- /* Placeholders are not configuration. The shipped profile leaves these
+       empty so the guards above fire, but a values file copied from the docs
+       can still carry the marker text through, and a pod that authenticates
+       nobody because its issuer is literally REPLACE_ME is the failure this
+       whole block exists to prevent.
+
+       The role mappings are scanned too. A placeholder there is not a
+       non-working deployment, it is a working one that authorizes exactly the
+       literal claim value "REPLACE_ME" — so every real caller is denied while
+       the chart reports success. */ -}}
+{{- range (concat (list $oidc.issuer $oidc.authorizationClaim) $oidc.audiences $explorer.allowedHosts $oidc.readerValues $oidc.contributorValues $oidc.fleetValues) -}}
+{{- if contains "REPLACE_ME" (toString .) -}}
+{{- fail (printf "explorer configuration still contains the placeholder %q: replace every REPLACE_ME before installing" (toString .)) -}}
+{{- end -}}
+{{- end -}}
+
+{{- /* One state root, one engine, no coordination protocol between two
+       processes over it. */ -}}
+{{- if gt (int $explorer.replicas) 1 -}}
+{{- fail "explorer.replicas must be 1: the corpus, workspace settings and durable policy catalog live in one state root on a ReadWriteOnce volume, and there is no coordination protocol between two processes over it. A second replica is not a scale-out, it is two writers to one engine" -}}
+{{- end -}}
+{{- if lt (int $explorer.replicas) 0 -}}
+{{- fail "explorer.replicas must be 0 or 1" -}}
+{{- end -}}
+
+{{- /* The mosaic budget is inert without a window to accumulate over. */ -}}
+{{- if and (gt (int $explorer.disclosure.mosaic.maxDomains) 0) (not $explorer.disclosure.mosaic.window) -}}
+{{- fail "explorer.disclosure.mosaic.window is required when maxDomains is above zero: the distinct-domain count accumulates over that window and never resets without one" -}}
+{{- end -}}
+
+{{- /* A credential that is never projected into the pod becomes a request-time
+       failure in whichever code path first needs the model. */ -}}
+{{- if $explorer.chat.provider -}}
+{{- if not $explorer.chat.model -}}
+{{- fail "explorer.chat.model is required when explorer.chat.provider is set" -}}
+{{- end -}}
+{{- if and (not (hasPrefix "http://127.0.0.1" $explorer.chat.baseURL)) (not (hasPrefix "http://localhost" $explorer.chat.baseURL)) -}}
+{{- if not $explorer.chat.credentialSecretName -}}
+{{- fail (printf "explorer.chat.credentialSecretName is required for a remote chat base URL (%q): the workspace reads %s at request time, and nothing projects it into the pod without a Secret" $explorer.chat.baseURL $explorer.chat.apiKeyEnv) -}}
+{{- end -}}
+{{- end -}}
+{{- end -}}
+{{- if and $explorer.embedding.provider (has $explorer.embedding.provider (list "openai" "voyage")) -}}
+{{- if not $explorer.embedding.credentialSecretName -}}
+{{- fail (printf "explorer.embedding.credentialSecretName is required for the %s embedding provider: it is unconditionally remote and needs a credential in the pod" $explorer.embedding.provider) -}}
+{{- end -}}
+{{- end -}}
+
+{{- /* The ask executor is bound by reference, and the registry only accepts a
+       reference the allow-list names. */ -}}
+{{- if $explorer.fleet.askExecutorRef -}}
+{{- if not (has $explorer.fleet.askExecutorRef $explorer.fleet.executorRefs) -}}
+{{- fail (printf "explorer.fleet.askExecutorRef %q must also appear in explorer.fleet.executorRefs, or registration stays fail-closed against it" $explorer.fleet.askExecutorRef) -}}
+{{- end -}}
+{{- if not $explorer.chat.provider -}}
+{{- fail "explorer.fleet.askExecutorRef requires a configured explorer.chat.provider: the grounded-reasoning executor has no model to run without one" -}}
+{{- end -}}
+{{- end -}}
+
+{{- /* Two listeners on one port silently means one of them is not serving. */ -}}
+{{- if eq (int $explorer.containerPort) (int $explorer.healthPort) -}}
+{{- fail "explorer.healthPort must differ from explorer.containerPort: they are two listeners and cannot share a port" -}}
+{{- end -}}
+{{- end -}}
